168:   public async execute(
169:     choice: RecoveryChoice,
170:     deps: {
171:       git: GitClient;
172:       workspaceManager: WorkspaceManager;
173:       prompts: RecoveryPrompts;
174:     },
175:   ): Promise<StaleRunRecoveryResult> {
176:     if (!this.tracker) {
177:       throw new Error("Cannot execute recovery actions without a tracker.");
178:     }
179:     const { git, workspaceManager, prompts } = deps;
180:     switch (choice) {
181:       case "cancel":
182:         return { action: "abort", message: "Recovery cancelled by developer.", rollbackDisabled: false };
183: 
184:       case "abandon": {
185:         this.tracker.markCompletedAndArchive();
186:         return { action: "proceed", message: "Stale run abandoned. Starting new loop run.", rollbackDisabled: false };
187:       }
188: 
189:       case "rollback": {
190:         if (!this.state.rollbackSnapshotId) {
191:           return {
192:             action: "abort",
193:             message: `Rollback requested for stale run ${this.state.runId}, but no rollback snapshot was recorded.`,
194:             rollbackDisabled: true,
195:           };
196:         }
197: 
198:         try {
199:           workspaceManager.adoptSnapshot(this.state.rollbackSnapshotId);
200:           const rollbackResult = await workspaceManager.rollback();
201:           if (!rollbackResult.success) {
202:             const detail = rollbackResult.snapshotPath
203:               ? ` Snapshot retained at ${rollbackResult.snapshotPath}.`
204:               : "";
205:             return {
206:               action: "abort",
207:               message: `Rollback failed for stale run ${this.state.runId}.${detail}`,
208:               rollbackDisabled: false,
209:             };
210:           }
211: 
212:           this.tracker.markCompletedAndArchive();
213:           workspaceManager.cleanupAll();
214:           return {
215:             action: "proceed",
216:             message: "Stale run rolled back. Starting fresh loop run.",
217:             rollbackDisabled: false,
218:           };
219:         } finally {
220:           workspaceManager.releaseWorkspaceLock();
221:         }
222:       }
223: 
224:       case "finishRollback": {
225:         const confirmed = await prompts.promptFinishRollbackConfirm();
226:         if (!confirmed) {
227:           return { action: "abort", message: "Finish rollback cancelled by developer.", rollbackDisabled: false };
228:         }
229: 
230:         if (!this.state.rollbackSnapshotId) {
231:           return {
232:             action: "abort",
233:             message: `Finish rollback requested for stale run ${this.state.runId}, but no rollback snapshot was recorded.`,
234:             rollbackDisabled: true,
235:           };
236:         }
237: 
238:         try {
239:           workspaceManager.adoptSnapshot(this.state.rollbackSnapshotId);
240:           const rollbackResult = await workspaceManager.rollback();
241: 
242:           if (!rollbackResult.success) {
243:             this.tracker.recordPanicUndo({
244:               phase: "rollback-failed",
245:               rollbackFailedAt: new Date().toISOString(),
246:               snapshotRetained: rollbackResult.snapshotRetained,
247:               snapshotPath: rollbackResult.snapshotPath,
248:               affectedPaths: rollbackResult.affectedPaths,
249:             });
250:             const detail = rollbackResult.snapshotPath
251:               ? ` Snapshot retained at ${rollbackResult.snapshotPath}.`
252:               : "";
253:             return {
254:               action: "abort",
255:               message: `Rollback failed for stale run ${this.state.runId}.${detail}`,
256:               rollbackDisabled: false,
257:             };
258:           }
259: 
260:           workspaceManager.cleanupAll();
261: 
262:           console.warn(`  ⚠ Issue-status restore not available during startup recovery. Issue statuses may need manual cleanup.`);
263: 
264:           if (hasRemoteDivergence(this.state.repoCwd)) {
265:             console.warn(`  ⚠ Loop-created commits may have been pushed to a remote. Remote cleanup is manual.`);
266:           }
267: 
268:           this.tracker.recordPanicUndo({
269:             phase: "rollback-completed",
270:             rollbackCompletedAt: new Date().toISOString(),
271:             snapshotRetained: rollbackResult.snapshotRetained,
272:             snapshotPath: rollbackResult.snapshotPath,
273:             affectedPaths: rollbackResult.affectedPaths,
274:           });
275: 
276:           this.tracker.markStatusAndArchive("interrupted", "panic-undo");
277:           return {
278:             action: "proceed",
279:             message: "Partial panic-undo rollback completed. Run archived as interrupted.",
280:             rollbackDisabled: false,
281:           };
282:         } finally {
283:           workspaceManager.releaseWorkspaceLock();
284:         }
285:       }
286: 
287:       case "resume": {
288:         try {
289:           await this.prepareResume(git, workspaceManager, prompts);
290:         } catch (error) {
291:           if (error instanceof AbandonStaleRunError) {
292:             this.tracker.markCompletedAndArchive();
293:             return {
294:               action: "proceed",
295:               message: "Stale run abandoned. Starting new loop run.",
296:               rollbackDisabled: false,
297:             };
298:           }
299:           throw error;
300:         }
301:         this.tracker.adoptOwnership();
302:         return { action: "proceed", rollbackDisabled: this.state.rollbackSnapshotId == null };
303:       }
304:     }
305:   }
