392: export async function handleStaleRun(
393:   tracker: LoopRunTracker,
394:   git: GitClient,
395:   workspaceManager: WorkspaceManager,
396:   prompts: RecoveryPrompts = ttyRecoveryPrompts,
397: ): Promise<StaleRunRecoveryResult> {
398:   const state = tracker.read();
399: 
400:   if (!state) {
401:     return { action: "proceed", rollbackDisabled: false };
402:   }
403: 
404:   if (!tracker.isStale()) {
405:     return {
406:       action: "abort",
407:       message: `Active loop run detected (PID ${state.owner.pid}). Cannot start a new loop while another is running.`,
408:       rollbackDisabled: false,
409:     };
410:   }
411: 
412:   // When relying on the default TTY prompts but no TTY is attached, there is no
413:   // way to surface a choice — abort. Tests injecting a custom RecoveryPrompts
414:   // bypass this guard since they don't need stdin.
415:   if (prompts === ttyRecoveryPrompts && !process.stdin.isTTY) {
416:     return {
417:       action: "abort",
418:       message: `Stale loop run detected (runId: ${state.runId}). Use interactive mode (TTY) to resume, rollback, or abandon the stale run. No default recovery action will be selected.`,
419:       rollbackDisabled: false,
420:     };
421:   }
422: 
423:   const staleRun = StaleRun.fromTracker(tracker);
424:   if (!staleRun) {
425:     return { action: "proceed", rollbackDisabled: false };
426:   }
427: 
428:   staleRun.normalizeCrashRules();
429: 
430:   const actions = staleRun.getAvailableActions();
431:   const choice = await prompts.promptChoice(staleRun.getState(), actions);
432:   if (!actions.includes(choice)) {
433:     return {
434:       action: "abort",
435:       message: `Stale loop run recovery choice '${choice}' is not available in the current recovery state.`,
436:       rollbackDisabled: false,
437:     };
438:   }
439: 
440:   return staleRun.execute(choice, { git, workspaceManager, prompts });
441: }
